const $=s=>document.querySelector(s);const data=await fetch('catalog.json').then(r=>{if(!r.ok)throw Error('清单载入失败');return r.json()}).catch(e=>{document.querySelector('.notice').textContent=e.message;return {models:[],images:[]}});let active=[];const styles=['原神参考 · 赛璐璐','终末地参考 · PBR 动漫','宫崎骏参考 · 水粉','BK 候选 · 未校准','手绘油画候选','Bloomwalker参考 · 柔绘'];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));$('#modelCount').textContent=data.models.length;$('#uiCount').textContent=data.images.length;styles.forEach((s,i)=>$('#style').add(new Option(s,String(i+1).padStart(2,'0'))));function subjects(){let a=data.models.filter(m=>$('#version').value==='all'||m.version===$('#version').value);let map=new Map(a.map(m=>[m.version+':'+m.subject_id,{label:m.subject+(m.version==='original'?' · 前版':''),key:m.version+':'+m.subject_id}]));$('#subject').replaceChildren(...[...map.values()].map(x=>new Option(x.label,x.key)));renderModels()};function releaseAll(){active.forEach(x=>{x.mv.remove();x.stage.querySelector('.load').hidden=false});active=[]}function renderModels(){releaseAll();let a=data.models.filter(m=>(m.version+':'+m.subject_id)===$('#subject').value&&($('#style').value==='all'||m.style_id===$('#style').value));$('#modelGrid').innerHTML=a.map(m=>`<article class="card"><div class="stage" data-id="${esc(m.id)}"><span class="index">${esc(m.style_id)} / 06</span>${m.preview?`<img class="model-poster" src="${esc(m.preview)}" alt="${esc(m.title)}预览" loading="lazy">`:""}<button class="load">载入实际模型</button></div><div class="card-body"><h3>${esc(styles[Number(m.style_id)-1]||m.style)}</h3><div class="meta"><span>${Number(m.actual_triangles).toLocaleString()} 三角面</span><span>${(m.bytes/1048576).toFixed(2)} MB</span></div><p><span class="badge">${m.version==='original'?'前版保留对照':'风格未通过 · 待重做'}</span> ${m.uncalibrated?'BK 未校准':''}</p><p>${esc(m.subject)} · ${esc(m.version_label)}<br>图集：${m.atlas_reuse?.length?'存在跨模型复用':'来源/复用待核'} · ${m.materials?.length||0} 个材质</p><a href="${esc(m.file)}" download>下载 GLB</a><details><summary>文件核验</summary><p>SHA256 ${esc(m.sha256)}<br>包内清单匹配：${m.manifest_hash_verified?'已核对':'未确认'}<br>此处为标准材质展示，不等于专属风格着色通过</p></details></div></article>`).join('')||'<p>此筛选下没有已恢复模型</p>';document.querySelectorAll('.stage .load').forEach(b=>b.onclick=()=>loadModel(b));}function loadModel(b){const stage=b.parentElement,m=data.models.find(x=>x.id===stage.dataset.id);const limit=innerWidth<600?1:2;while(active.length>=limit){const x=active.shift();x.mv.remove();x.stage.querySelector('.load').hidden=false}const mv=document.createElement('model-viewer');mv.src=m.file;mv.alt=m.title;mv.setAttribute('camera-controls','');mv.setAttribute('touch-action','pan-y');mv.setAttribute('shadow-intensity','0.6');mv.setAttribute('exposure','1');mv.setAttribute('camera-orbit','35deg 75deg auto');mv.setAttribute('field-of-view','30deg');mv.setAttribute('interaction-prompt','none');b.hidden=true;stage.append(mv);active.push({stage,mv});mv.addEventListener('error',()=>{mv.remove();b.hidden=false;b.textContent='载入失败 · 点击重试';active=active.filter(x=>x.mv!==mv)});let syncing=false;mv.addEventListener('camera-change',e=>{if(e.detail.source!=='user-interaction'||syncing)return;const o=mv.getCameraOrbit();active.filter(x=>x.mv!==mv).forEach(x=>{syncing=true;x.mv.cameraOrbit=`${o.theta}rad ${o.phi}rad auto`;syncing=false})});}$('#resetCameras').onclick=()=>active.forEach(x=>{x.mv.cameraOrbit='35deg 75deg auto';x.mv.fieldOfView='30deg'});$('#unload').onclick=releaseAll;$('#version').onchange=subjects;$('#subject').onchange=renderModels;$('#style').onchange=renderModels;const categories=[...new Set(data.images.map(i=>i.category))];categories.forEach(c=>$('#uiCategory').add(new Option(c,c)));function renderImages(){let q=$('#uiSearch').value.trim();let a=data.images.filter(i=>($('#uiCategory').value==='all'||i.category===$('#uiCategory').value)&&(!q||(i.title+' '+i.category).includes(q)));$('#uiGrid').innerHTML=a.map(i=>`<article class="card"><button class="image-open" data-image="${esc(i.file)}" data-title="${esc(i.title)}"><img src="${esc(i.file)}" alt="${esc(i.title)}" loading="lazy"></button><div class="card-body"><h3>${esc(i.title)}</h3><div class="meta"><span>${i.width} × ${i.height} 原生像素</span><span>${esc(i.category)}</span></div><p>${i.approved?'用户认可方向 · ':''}${esc(i.status||'设计候选 · 未实装验证')}</p></div></article>`).join('')||'<p>未找到匹配参考图</p>';}$('#uiCategory').onchange=renderImages;$('#uiSearch').oninput=renderImages;document.addEventListener('click',e=>{const b=e.target.closest('.image-open');if(!b)return;$('#largeImage').src=b.dataset.image;$('#largeImage').classList.remove('zoomed');$('#imageTitle').textContent=b.dataset.title;$('#imageDownload').href=b.dataset.image;$('#lightbox').showModal()});$('#largeImage').onclick=e=>e.target.classList.toggle('zoomed');$('#closeImage').onclick=()=>$('#lightbox').close();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{releaseAll();document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!==b.dataset.tab);$('#heading').textContent={models:'让差别，看得见',ui:'每个界面，保留原貌',progress:'睡后做了什么，直接打开测试',evidence:'完成到哪里，证据就到哪里'}[b.dataset.tab]});subjects();renderImages();
